def effect(world) -> float:
    import numpy as np
    from collections import defaultdict

    records = []
    for s in world.get('series', {}).values():
        days = np.asarray(s.get('days', []), dtype=np.int64)
        P = np.asarray(s.get('P', []), dtype=float)
        if len(days) < 10 or P.ndim != 2 or P.shape[0] != len(days):
            continue
        order = np.argsort(days)
        days, P = days[order], P[order]
        observations = {}
        for i in range(1, len(days)):
            if days[i] - days[i-1] != 1:
                continue
            ok = np.isfinite(P[i]) & np.isfinite(P[i-1])
            if not np.any(ok):
                continue
            a, b = P[i-1, ok], P[i, ok]
            tol = 1e-8 * np.maximum(1.0, np.abs(a))
            observations[int(days[i])] = float(np.mean((a-b > tol).astype(float) - (b-a > tol).astype(float)))
        if len(observations) < 8:
            continue
        # Remove each series' regular weekday schedule.
        weekday = defaultdict(list)
        for d, v in observations.items():
            weekday[(d-1) % 7].append(v)
        means = {w: float(np.mean(v)) for w, v in weekday.items()}
        x = {d: v - means[(d-1) % 7] for d, v in observations.items()}
        # Remove predictable own-series one-day dynamics.
        paired = [d for d in x if d-1 in x]
        if len(paired) < 6:
            continue
        prev = np.array([x[d-1] for d in paired])
        now = np.array([x[d] for d in paired])
        design = np.column_stack([np.ones(len(prev)), prev])
        coef = np.linalg.lstsq(design, now, rcond=None)[0]
        residual = {d: float(x[d] - coef[0] - coef[1]*x[d-1]) for d in paired}
        scale = float(np.std(list(residual.values())))
        if scale < 1e-12:
            continue
        residual = {d: v/scale for d, v in residual.items()}
        m = s.get('meta', {})
        key = tuple(str(m.get(k, '')) for k in ('instrument_class', 'gpu_model', 'pricing_tier'))
        records.append((str(m.get('source_id', '')), key, residual))

    evidence = defaultdict(list)
    for i, (sa, ka, a) in enumerate(records):
        for sb, kb, b in records[i+1:]:
            if sa == sb or ka != kb:
                continue
            if sa > sb:
                source_pair, left, right = (sb, sa), b, a
            else:
                source_pair, left, right = (sa, sb), a, b
            # Compare both directions on exactly the same calendar windows.
            dates = [d for d in left if d+1 in left and d in right and d+1 in right]
            if len(dates) < 6:
                continue
            asymmetry = np.mean([left[d]*right[d+1] - right[d]*left[d+1] for d in dates])
            evidence[source_pair].append((float(asymmetry), len(dates)))
    if not evidence:
        return 0.0
    scores = []
    for entries in evidence.values():
        total = sum(n for _, n in entries)
        directional = sum(v*n for v, n in entries) / total
        scores.append(abs(directional))
    result = float(np.mean(scores))
    return result if np.isfinite(result) else 0.0

def effect(world):
    import numpy as np
    from collections import defaultdict

    panels = []
    market = defaultdict(list)
    for s in world.get('series', {}).values():
        days = np.asarray(s.get('days', []), dtype=np.int64)
        P = np.asarray(s.get('P', []), dtype=float)
        if P.ndim != 2 or len(days) < 5 or P.shape[0] != len(days):
            continue
        valid = np.isfinite(P[1:]) & np.isfinite(P[:-1])
        valid &= (np.diff(days) == 1)[:, None]
        changed = valid & (np.abs(P[1:] - P[:-1]) > 1e-9)
        active = changed.sum(axis=0) >= 2
        if not np.any(active):
            continue
        dd = days[1:]
        denom = valid[:, active].sum(axis=1)
        rate = np.divide(changed[:, active].sum(axis=1), denom,
                         out=np.full(len(dd), np.nan), where=denom > 0)
        for d, r in zip(dd, rate):
            if np.isfinite(r):
                market[int(d)].append(float(r))
        groups = defaultdict(list)
        for j, slot in enumerate(s.get('slots', [])):
            if j < P.shape[1] and active[j]:
                provider = str(slot).split('|')[0].strip().lower()
                groups[provider].append(j)
        meta = s.get('meta', {})
        for provider, jj in groups.items():
            den = valid[:, jj].sum(axis=1)
            rr = np.divide(changed[:, jj].sum(axis=1), den,
                           out=np.full(len(dd), np.nan), where=den > 0)
            ok = np.isfinite(rr)
            if ok.sum() >= 8:
                panels.append((provider, meta.get('gpu_model'), dd[ok], rr[ok]))

    global_rate = {d: float(np.mean(v)) for d, v in market.items()}
    residuals = []
    for provider, gpu, days, rate in panels:
        weekday = (days - 1) % 7
        g = np.array([global_rate.get(int(d), 0.0) for d in days])
        X = np.column_stack([np.ones(len(days)), g] +
                            [(weekday == k).astype(float) for k in range(6)])
        residual = rate - X.dot(np.linalg.lstsq(X, rate, rcond=None)[0])
        if np.std(residual) > 1e-8:
            residuals.append((provider, gpu, days, residual))

    scores = []
    for i, (provider, gpu, days, r) in enumerate(residuals):
        for provider2, gpu2, days2, r2 in residuals[i + 1:]:
            if provider != provider2 or gpu == gpu2:
                continue
            common, a, b = np.intersect1d(days, days2, return_indices=True)
            if len(common) < 8:
                continue
            x = r[a] - np.mean(r[a])
            y = r2[b] - np.mean(r2[b])
            den = float(np.sqrt(np.dot(x, x) * np.dot(y, y)))
            if den > 1e-12:
                scores.append(float(np.dot(x, y) / den))
    return float(np.mean(scores)) if scores else 0.0
